function f(e,t=.25){const n=e.length;if(n===0)return[];let o=[];o.push({...e[0]});for(let u=0;u<n-1;u++){const r=e[u],l=e[u+1];o.push({x:r.x*(1-t)+l.x*t,y:r.y*(1-t)+l.y*t},{x:r.x*t+l.x*(1-t),y:r.y*t+l.y*(1-t)})}return n>1&&o.push({...e[n-1]}),o}function p(e,t=.25){const n=e.length;if(n===0)return[];let o=[],u=1-t,r=t;o.push([...e[0]]);for(let l=0;l<n-1;l++){const c=e[l],h=e[l+1];o.push([c[0]*u+h[0]*r,c[1]*u+h[1]*r],[c[0]*r+h[0]*u,c[1]*r+h[1]*u])}return n>1&&o.push([...e[n-1]]),o}function s(e,t,n=.25){let o=e;for(let u=0;u<t;u++)o=f(o,n);return o}function x(e,t,n=.25){let o=e;for(let u=0;u<t;u++)o=p(o,n);return o}export{x as a,s as c};
